#!/usr/bin/env bash
# PreToolUse(Edit|Write): block hand-edits to generated files, pointing at the script to run instead.
set -uo pipefail

input="$(cat)"
file_path="$(printf '%s' "$input" | jq -r '.tool_input.file_path // empty')"

if [[ -z "$file_path" ]]; then
  exit 0
fi

case "$file_path" in
  */docs/RULES.md | docs/RULES.md)
    echo "docs/RULES.md is generated. Run 'npm run rules:doc' instead of editing it by hand." >&2
    exit 2
    ;;
  */packages/core/src/gen/* | packages/core/src/gen/*)
    echo "packages/core/src/gen/** is generated proto code. Regenerate it with the proto codegen script instead of editing by hand." >&2
    exit 2
    ;;
  */cli/Sources/StoreReadyCore/Generated/* | cli/Sources/StoreReadyCore/Generated/*)
    echo "cli/Sources/StoreReadyCore/Generated/** is generated proto code. Regenerate it with the proto codegen script instead of editing by hand." >&2
    exit 2
    ;;
  */fixtures/files/* | fixtures/files/*)
    echo "fixtures/files/** is generated by fixtures/generators/ scripts. Use the make-fixture skill instead of editing a fixture by hand." >&2
    exit 2
    ;;
  *)
    exit 0
    ;;
esac
